/** Seeded conversations — GENERATED by the engine, not written by hand.
 *
 * Each script is a list of real turns replayed through the same path a live turn
 * takes, so a fixture cannot contain a card, a chip row or a sentence the engine
 * would not actually produce. Writing transcripts by hand would eventually put a
 * plausible wine claim on screen that no dataset row backs — the precise failure this
 * product exists to prevent.
 *
 * Between them the scripts cover every state worth designing for: a full three-
 * question interview, a refine chain, FR-13's abstention, an out-of-scope question, an
 * interview still in progress with inferred slots, a stale dataset version, and an
 * archived conversation.
 */

import * as db from "../db";
import { NEW_TITLE, seedTurn } from "../stream";

interface Turn {
  content: string;
  chipId?: string;
}

interface Script {
  /** Hours before now that the conversation started. */
  hoursAgo: number;
  /** Pin an older artifact version to exercise `dataset_version_stale`. */
  datasetVersion?: string;
  archived?: boolean;
  turns: Turn[];
}

const SCRIPTS: Script[] = [
  // A full three-question interview: style typed, sweetness and body tapped.
  {
    hoursAgo: 2,
    turns: [
      { content: "I want a red" },
      { content: "Not sweet at all", chipId: "sweetness:dry" },
      { content: "Rich and bold", chipId: "body:full" },
    ],
  },
  // Free text that answers three questions at once, then a refine chain.
  {
    hoursAgo: 6,
    turns: [
      { content: "something light and red, not sweet" },
      { content: "bolder", chipId: "bolder" },
      { content: "smoother", chipId: "smoother" },
    ],
  },
  // FR-13: a dessert wine that is not sweet at all does not exist in the dataset, and
  // the answer says so rather than serving five sweet wines.
  {
    hoursAgo: 9,
    turns: [
      { content: "I'd like a dessert wine" },
      { content: "Not sweet at all", chipId: "sweetness:dry" },
    ],
  },
  // Out of scope: price is not in the dataset and never will be.
  {
    hoursAgo: 52,
    turns: [{ content: "a crisp white, nothing sweet" }, { content: "how much does it cost?" }],
  },
  // An interview still in progress: two slots inferred from free text, one pending.
  {
    hoursAgo: 96,
    turns: [{ content: "a buttery white please" }],
  },
  // Served from an older artifact, so the stale-version notice has somewhere to render.
  {
    hoursAgo: 480,
    datasetVersion: "seed-0.0",
    turns: [{ content: "a bold red, nothing too sweet" }],
  },
  // Archived, so the archived toggle is not an empty screen.
  {
    hoursAgo: 240,
    archived: true,
    turns: [{ content: "sparkling, nothing sweet" }],
  },
];

export function seedConversations(): void {
  const now = Date.now();
  for (const script of SCRIPTS) {
    const start = new Date(now - script.hoursAgo * 3_600_000);
    const conversation = db.createConversation(NEW_TITLE, start, script.datasetVersion);
    script.turns.forEach((turn, index) => {
      seedTurn({
        cid: conversation.id,
        utterance: turn.content,
        chipId: turn.chipId ?? null,
        at: new Date(start.getTime() + index * 90_000),
      });
    });
    if (script.archived) db.patchConversation(conversation.id, { archived: true });
  }
  // The seeded conversations are history, not something the user just did: the age
  // gate still has to be passed, because that is the first screen to get right.
  db.db.age_confirmed = false;
  db.save();
}
